#!/bin/bash

docker run -v /media/DATA/:/media/DATA/ broadinstitute/gatk gatk VariantRecalibrator -V /media/DATA/pregloss_project/ploss_analysis.v3.VEP.vcf --trust-all-polymorphic -tranche 100.0 -tranche 99.95 -tranche 99.9 -tranche 99.8 -tranche 99.6 -tranche 99.5 -tranche 99.4 -tranche 99.3 -tranche 99.0 -tranche 98.0 -tranche 97.0 -tranche 90.0 -an QD -an MQRankSum -an ReadPosRankSum -an FS -an MQ -an SOR -an DP -mode SNP --max-gaussians 6 -resource:hapmap,known=false,training=true,truth=true,prior=15 /media/DATA/ott_ngs/data/grch38/hapmap_3.3.hg38.vcf.gz -resource:omni,known=false,training=true,truth=true,prior=12 /media/DATA/ott_ngs/data/grch38/1000G_omni2.5.hg38.vcf.gz -resource:1000G,known=false,training=true,truth=false,prior=10 /media/DATA/ott_ngs/data/grch38/1000G_phase1.snps.high_confidence.hg38.vcf.gz -resource:dbsnp,known=true,training=false,truth=false,prior=7 /media/DATA/ott_ngs/data/grch38/Homo_sapiens_assembly38.dbsnp138.vcf -O /media/DATA/pregloss_project/vqsr_snps.recal --tranches-file /media/DATA/pregloss_project/vqsr_snp.tranches --rscript-file /media/DATA/pregloss_project/vqsr_snp_script.R

docker run -v /media/DATA/:/media/DATA broadinstitute/gatk gatk VariantRecalibrator -V /media/DATA/pregloss_project/ploss_analysis.v3.VEP.vcf --trust-all-polymorphic -tranche 100.0 -tranche 99.95 -tranche 99.9 -tranche 99.8 -tranche 99.6 -tranche 99.5 -tranche 99.4 -tranche 99.3 -tranche 99.0 -tranche 98.0 -tranche 97.0 -tranche 90.0 -an FS -an ReadPosRankSum -an MQRankSum -an QD -an SOR -an DP -mode INDEL --max-gaussians 4 -resource:mills,known=false,training=true,truth=true,prior=12 /media/DATA/ott_ngs/data/grch38/Mills_and_1000G_gold_standard.indels.hg38.vcf -resource:dbsnp,known=true,training=false,truth=false,prior=2 /media/DATA/ott_ngs/data/grch38/Homo_sapiens_assembly38.dbsnp138.vcf -O /media/DATA/pregloss_project/vqsr_indel.recal --tranches-file /media/DATA/pregloss_project/vqsr_indel.tranches --rscript-file /media/DATA/pregloss_project/vqsr_indel_script.R

docker run -v /media/DATA/:/media/DATA broadinstitute/gatk gatk ApplyVQSR -V /media/DATA/pregloss_project/ploss_analysis.v3.VEP.vcf  --recal-file /media/DATA/pregloss_project/vqsr_indel.recal --tranches-file /media/DATA/pregloss_project/vqsr_indel.tranches --truth-sensitivity-filter-level 90.0 --create-output-variant-index true -mode INDEL -O /media/DATA/pregloss_project/ploss_analysis.v3.VEP.indel_vqsr.vcf

docker run -v /media/DATA/:/media/DATA broadinstitute/gatk gatk ApplyVQSR -V /media/DATA/pregloss_project/ploss_analysis.v3.VEP.indel_vqsr.vcf  --recal-file /media/DATA/pregloss_project/vqsr_snps.recal --tranches-file /media/DATA/pregloss_project/vqsr_snp.tranches --truth-sensitivity-filter-level 99.3 --create-output-variant-index true -mode SNP -O /media/DATA/pregloss_project/ploss_analysis.v3.VEP.Recalibrated.vcf
